flow.set("toll_db_ready",false); msg.topic="PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    uid TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    balance INTEGER NOT NULL DEFAULT 0 CHECK(balance >= 0),
    created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id TEXT NOT NULL UNIQUE,
    user_id INTEGER,
    uid TEXT NOT NULL,
    amount INTEGER NOT NULL DEFAULT 0,
    balance_before INTEGER,
    balance_after INTEGER,
    status TEXT NOT NULL CHECK(status IN ('PAID','DENIED')),
    reason TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
    FOREIGN KEY(user_id) REFERENCES users(id)
        ON UPDATE CASCADE
        ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_transactions_time
ON transactions(created_at);

CREATE INDEX IF NOT EXISTS idx_transactions_uid
ON transactions(uid);

CREATE TRIGGER IF NOT EXISTS toll_debit_after_insert
AFTER INSERT ON transactions WHEN NEW.status = 'PAID'
BEGIN
 UPDATE users SET balance=balance-NEW.amount, updated_at=datetime('now','localtime')
 WHERE id=NEW.user_id AND balance>=NEW.amount;
 SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'DEBIT_FAILED') END;
END;

CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1),fee INTEGER NOT NULL CHECK(fee>=0 AND fee<=1000000000));
INSERT OR IGNORE INTO settings(id,fee) VALUES(1,5000);
";return msg;

const p=msg.payload;
if (!p || p.group_id!=='kelompok-01' || msg.retain) return null;
const uid=String(p.uid||'').trim().toUpperCase();
if (!/^(?:[0-9A-F]{8}|[0-9A-F]{14}|[0-9A-F]{20})$/.test(uid) || !p.node_id || typeof p.event_id!=='string' || !p.event_id || p.event_id.length>160) {node.warn('Event RFID tidak valid');return null;}
if (!flow.get('toll_db_ready')) {node.error('Database belum siap',msg);return null;}
msg._event={...p,uid};
if(p.mode==='REGISTER') return [null,{payload:{action:'registration_uid',uid,event_id:p.event_id,node_id:p.node_id}}];
if(p.mode!=='PAYMENT') return null;
msg.params={$event_id:p.event_id,$uid:uid};
return [msg,null];

const e=msg._event; const t=Array.isArray(msg.payload)?msg.payload[0]:null;
if(!t || t.uid!==e.uid){node.error('Hasil transaksi tidak cocok',msg);return null;}
const reasonText={PAYMENT_SUCCESS:'Pembayaran berhasil',UID_NOT_REGISTERED:'UID kartu tidak terdaftar',INSUFFICIENT_BALANCE:'Saldo tidak cukup'}[t.reason]||t.reason;
const mqtt={topic:`toll/${e.group_id}/esp32/command`,payload:{command:'ACCESS_RESULT',event_id:e.event_id,result:t.status,reason:reasonText},qos:0,retain:false};
let seen=context.get('seen')||{};const now=Date.now();for(const k of Object.keys(seen)) if(now-seen[k]>300000) delete seen[k];
const duplicate=Boolean(seen[e.event_id]); seen[e.event_id]=now;context.set('seen',seen);
const ui={payload:{action:'access_result',event_id:e.event_id,uid:e.uid,result:t.status,reason:t.reason,reason_text:reasonText,user:t.user_id?{name:t.name,balance_before:t.balance_before,balance_after:t.balance_after}:null}};
return [null,mqtt,duplicate?null:ui];

const p = msg.payload || {};
if (p.group_id !== 'kelompok-01') return null;
if (p.status === 'EXECUTION_COMPLETE') {
    return {payload:{action:'standby',message:'Silakan tap kartu',last_result:p.result,event_id:p.event_id}};
}
if (p.status === 'ONLINE') {
    return {payload:{action:'device_online',message:'Perangkat terhubung'}};
}
return null;

const ADMIN_USERNAME = 'admin';
const ADMIN_PASSWORD = 'admin123';
const SESSION_MS = 30 * 60 * 1000;
const p = msg.payload || {};
const action = String(p.action || '');
let sessions = flow.get('toll_admin_sessions') || {};
const now = Date.now();
for (const key of Object.keys(sessions)) {
    if (sessions[key].expires < now) delete sessions[key];
}

function direct(payload) { return [{payload,_client:msg._client},null,null,null,null,null,null]; }
const socketId=msg._client && msg._client.socketId;
if (!socketId) return null;
function cleanUid(value) { return String(value || '').trim().toUpperCase(); }

if (action === 'admin_login') {
    if (p.username === ADMIN_USERNAME && p.password === ADMIN_PASSWORD) {
        const token = `${now}-${Math.random().toString(36).slice(2,14)}`;
        sessions[token] = {expires:now+SESSION_MS,socketId};
        flow.set('toll_admin_sessions',sessions);
        return direct({action:'login_result',success:true,token,message:'Login berhasil'});
    }
    return direct({action:'login_result',success:false,message:'Username atau password salah'});
}

const token = String(p.token || '');
if (!token || !sessions[token] || sessions[token].expires < now || sessions[token].socketId !== socketId) {
    return direct({action:'session_expired',message:'Sesi berakhir, silakan login kembali'});
}
sessions[token] = {expires:now+SESSION_MS,socketId};
flow.set('toll_admin_sessions',sessions);

if (action === 'admin_logout') {
    delete sessions[token];
    flow.set('toll_admin_sessions',sessions);
    return direct({action:'logout_result'});
}

if (!flow.get('toll_db_ready')) return direct({action:'operation_result',success:false,message:'Database belum siap. Periksa Debug.'});

if(action==='get_settings'){msg.params={};return [null,null,null,null,null,msg,null];}
if(action==='set_fee'){
 const fee=Number(p.fee);
 if(p.fee==='' || p.fee==null || !Number.isSafeInteger(fee)||fee<0||fee>1000000000)return direct({action:'operation_result',success:false,message:'Biaya harus berupa rupiah bulat antara 0 sampai 1 miliar'});
 msg.params={$fee:fee};msg._admin_action='fee_update';return [null,null,null,null,null,null,msg];
}
if (action === 'register_user') {
    const uid = cleanUid(p.uid);
    const name = String(p.name || '').trim();
    const balance = Number(p.balance);
    if (! /^(?:[0-9A-F]{8}|[0-9A-F]{14}|[0-9A-F]{20})$/.test(uid) || !name || name.length>100 || p.balance==='' || p.balance==null || !Number.isSafeInteger(balance) || balance < 0) {
        return direct({action:'operation_result',success:false,message:'Data pendaftaran tidak valid'});
    }
    msg.topic = 'INSERT INTO users (uid,name,balance) VALUES (?,?,?) ON CONFLICT(uid) DO NOTHING RETURNING id,uid,name,balance';
    msg.params = {$uid:uid,$name:name,$balance:balance};
    msg._admin_action = 'register';
    return [null,msg,null,null,null];
}

if (action === 'topup_balance') {
    const uid = cleanUid(p.uid);
    const amount = Number(p.amount);
    if (! /^(?:[0-9A-F]{8}|[0-9A-F]{14}|[0-9A-F]{20})$/.test(uid) || !Number.isSafeInteger(amount) || amount <= 0) {
        return direct({action:'operation_result',success:false,message:'UID atau nominal isi saldo tidak valid'});
    }
    msg.topic = 'UPDATE users SET balance = balance + ?, updated_at = datetime(\'now\',\'localtime\') WHERE uid = ? RETURNING id,uid,name,balance';
    msg.params = {$amount:amount,$uid:uid};
    msg._admin_action = 'topup';
    return [null,null,msg,null,null];
}

if (action === 'get_users') {
    msg.topic = 'SELECT id,uid,name,balance,created_at,updated_at FROM users ORDER BY name';
    msg.payload = [];
    msg._admin_action = 'users';
    return [null,null,null,msg,null];
}

if (action === 'get_history') {
    msg.topic = `SELECT t.id,t.created_at,t.uid,COALESCE(u.name,'Tidak terdaftar') AS name,t.amount,t.balance_before,t.balance_after,t.status,t.reason FROM transactions t LEFT JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 200`;
    msg.payload = [];
    msg._admin_action = 'history';
    return [null,null,null,null,msg];
}

return direct({action:'operation_result',success:false,message:'Perintah admin tidak dikenali'});

const rows = Array.isArray(msg.payload) ? msg.payload : [];
let payload;
switch (msg._admin_action) {
    case 'register':
        payload = rows.length ? {action:'operation_result',success:true,message:'Kartu berhasil didaftarkan'} : {action:'operation_result',success:false,message:'UID sudah terdaftar'};
        break;
    case 'topup':
        payload = rows.length ? {action:'operation_result',success:true,message:`Isi saldo berhasil. Saldo baru Rp ${Number(rows[0].balance).toLocaleString('id-ID')}`} : {action:'operation_result',success:false,message:'UID tidak ditemukan'};
        break;
    case 'users':
        payload = {action:'users_data',users:rows};
        break;
    case 'history':
        payload = {action:'history_data',history:rows};
        break;
    default:
        return null;
}
payload.operation = msg._admin_action;
return {payload,_client:msg._client};

const row=Array.isArray(msg.payload)?msg.payload[0]:null;
if(!row){node.error('Biaya belum tersedia',msg);return null;}
const fee=Number(row.fee);const setting={payload:{action:'fee_updated',fee}};
if(msg._admin_action==='fee_update')return [setting,{_client:msg._client,payload:{action:'operation_result',operation:'fee_update',success:true,message:'Biaya sekali tap berhasil diperbarui',fee}}];
if(msg._client){setting._client=msg._client;return msg._public_request?[setting,null]:[null,setting];}
return [setting,null];
